drop trigger immutable_ruby_revision on public.ruby_card_revisions; create function private.guard_ruby_revision() returns trigger language plpgsql set search_path='' as $$begin if pg_trigger_depth()>1 and new.edited_by is null and (to_jsonb(new)-'edited_by')=(to_jsonb(old)-'edited_by') then return new;end if;raise exception 'Card revisions are immutable';end$$; create trigger immutable_ruby_revision before update on public.ruby_card_revisions for each row execute function private.guard_ruby_revision();
